data.query:
query Inventory($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        serialNumber
        quantity {
          value
          unitId
        }
        storageUnitId
        inventoryPickSteps{
          edges{
            node{
              allocatedQuantity{
                _aggregate{
                  value{
                    sum
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

