/* This will filter inventory that will be used for the picking process. */
/* This will use an optional storageUnitId to find location only in that area. */

(
  $pickOptions := $appConfig.pickOptions;
  $inventoryMethod := $pickOptions.method;
  $field := $pickOptions.options[value = $inventoryMethod].field;
  $storageFilter := $isNilOrEmpty($state.context.INPUT.storageUnitId) ? {} : {"storageUnitId": {"_eq": $state.context.INPUT.storageUnitId}};
  $ignoreFilter := $isNilOrEmpty($state.context.INPUT.ignoreInventoryId) ? {} : {"_not": {"id": {"_eq": $state.context.INPUT.ignoreInventoryId}}};

  {
    "where": $merge([{
      "shippable": { "_eq": true },
      "active": { "_eq": true },
      "productId": {"_eq": $state.context.INPUT.productId},
      "handlingUnit": {"loadId":{"_isNull": true}},
      "inventoryStatusId": {"_eq": "ok"}
    }, $storageFilter, $ignoreFilter]),
    "orderBy": $isNotNilOrEmpty($field) ? [
      {
        "direction": "asc",
        "field": $field
      }
    ]
  }
)

