(
  $allInventory := inventory.edges.node;
  $defaultToZero := function($v){ $coalesce([$v, 0]) };
  $primerAcc := {
    "crrQty":0,
    "inventories":[]
  };

  $recursiveTakeRequiredInventories := function($arr, $index, $acc){(
    $index < $count($arr)? (

      $acc.crrQty >= $state.context.INPUT.quantity?
