          } |]
        )
      )
    )
    :
    $acc

  )};

  $steps := $recursiveTakeRequiredInventories(
    $allInventory[ $defaultToZero( inventoryPickSteps.edges.node.allocatedQuantity._aggregate.value.sum) < quantity.value ],
    0,
